select jsonb_build_object(
    'database', (select jsonb_build_object('name',datname,'owner',pg_get_userbyid(datdba),'acl',datacl::text) from pg_database where datname=current_database()),
    'schemas', (select jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) order by nspname) from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema'),
    'relations', (select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rowSecurity',c.relrowsecurity,'forcedRowSecurity',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema'),
    'functions', (select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema'),
    'columnAcls', (select jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'column',a.attname,'acl',a.attacl::text) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where a.attacl is not null and n.nspname !~ '^pg_' and n.nspname<>'information_schema'),
    'types', (select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl::text) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema'),
    'defaultAcls', (select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(defaclrole),'namespace',defaclnamespace::regnamespace::text,'type',defaclobjtype,'acl',defaclacl::text)) from pg_default_acl),
    'roles', (select jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'superuser',rolsuper,'createDb',rolcreatedb,'createRole',rolcreaterole,'replication',rolreplication,'bypassRls',rolbypassrls) order by rolname) from pg_roles where rolname !~ '^pg_'))